// Media test: can a native surface play anything richer than a CSS sprite?
// Each case wraps a tiny clip (a coloured square that slides, frames
// numbered 1-8) in an SVG, since Svg is the only picture desktop, VS Code
// and mobile draw. The base64 strings are generated; regenerate rather than
// hand-edit.

export const TEST_GIF_BASE64 =
  ''

export const TEST_WEBM_BASE64 =
  ''

const SIZE = 96

/** An animated GIF inside an SVG <image>. */
export function gifInSvg(): string {
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" ` +
    `viewBox="0 0 32 32" width="${SIZE}" height="${SIZE}">` +
    `<image width="32" height="32" style="image-rendering:pixelated" ` +
    `href="data:image/gif;base64,${TEST_GIF_BASE64}" ` +
    `xlink:href="data:image/gif;base64,${TEST_GIF_BASE64}"/></svg>`
  )
}

/** A looping, muted WebM inside an SVG <foreignObject> <video>. */
export function webmInSvg(): string {
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" width="${SIZE}" height="${SIZE}">` +
    `<foreignObject x="0" y="0" width="32" height="32">` +
    `<video xmlns="http://www.w3.org/1999/xhtml" autoplay="" muted="" loop="" playsinline="" ` +
    `width="32" height="32" style="image-rendering:pixelated" ` +
    `src="data:video/webm;base64,${TEST_WEBM_BASE64}"></video>` +
    `</foreignObject></svg>`
  )
}

export type MediaCase = { key: string; label: string; source: string; isInteractive: boolean }

/** A and B differ only in how the surface draws the Svg; C tries real video. */
export function mediaCases(): MediaCase[] {
  return [
    { key: 'gif-frame', label: 'A · GIF in SVG, sandboxed frame', source: gifInSvg(), isInteractive: true },
    { key: 'gif-image', label: 'B · GIF in SVG, plain image', source: gifInSvg(), isInteractive: false },
    { key: 'webm-frame', label: 'C · WebM in SVG, sandboxed frame', source: webmInSvg(), isInteractive: true },
  ]
}

files.hooks/net-probe.ts:
// Network probes for /eidola: can hook code on this session's host reach
// the places a Shrine bridge would post to? In a cloud session the host is
// the cloud machine, so 127.0.0.1 there is the container, not your computer.

// The probe itself (probeLine) lives in register.tsx: the engine follows $
// only into functions declared in the same file.

export type NetProbe = { label: string; url: string }

export const NET_PROBES: readonly NetProbe[] = [
  { label: 'eidola.app (hosted relay)', url: 'https://eidola.app/' },
  { label: 'example.com (control)', url: 'https://example.com/' },
  { label: 'api.github.com (a host cloud environments usually allow)', url: 'https://api.github.com/' },
  { label: 'Shrine on this host (127.0.0.1:9743)', url: 'http://127.0.0.1:9743/shrine/' },
]

export const PROBE_TIMEOUT_MS = 6000

export type Outcome =
  | { kind: 'status'; status: number }
  | { kind: 'error'; message: string }
  | { kind: 'timeout' }

function shorten(text: string, max = 140): string {
  const one = text.replace(/\s+/g, ' ').trim()
  return one.length > max ? `${one.slice(0, max - 1)}…` : one
}

export function describeOutcome(probe: NetProbe, outcome: Outcome): string {
  switch (outcome.kind) {
    case 'status':
      return `${probe.label}: reached, HTTP ${outcome.status}`
    case 'timeout':
      return `${probe.label}: no answer in ${PROBE_TIMEOUT_MS / 1000}s`
    case 'error':
      return `${probe.label}: failed (${shorten(outcome.message) || 'no reason given'})`
  }
}

files.hooks/placement.ts:
// Where the Vessel appears. The Engram suggests, the person decides:
// the `placement` option (in /config, or `/eidola place <where>`) wins,
// and its `default` value defers to the awake Engram's suggestion.

import type { PluginOptions } from 'claude-code'

export const PLACEMENT_SETTINGS = ['default', 'both', 'pane', 'band', 'auto'] as const
export type PlacementSetting = (typeof PLACEMENT_SETTINGS)[number]
export type Placement = Exclude<PlacementSetting, 'default'>

/** What an Engram that names no placement gets. */
export const FALLBACK_PLACEMENT: Placement = 'auto'

export const PLACEMENT_HELP: Record<PlacementSetting, string> = {
  default: "the awake Engram's suggestion (auto, if it has none)",
  both: 'pane and band',
  pane: 'pane only',
  band: 'band only; the pane opens only when you ask (/eidola)',
  auto: 'band only while no pane is placed',
}

export function isPlacementSetting(value: unknown): value is PlacementSetting {
  return typeof value === 'string' && (PLACEMENT_SETTINGS as readonly string[]).includes(value)
}

export function readPlacement(options: PluginOptions): PlacementSetting {
  const value = options['placement']
  return isPlacementSetting(value) ? value : 'default'
}

export function readStatusLine(options: PluginOptions): boolean {
  return options['statusLine'] !== false
}

export function effectivePlacement(setting: PlacementSetting, engramDefault: Placement | undefined): Placement {
  return setting === 'default' ? (engramDefault ?? FALLBACK_PLACEMENT) : setting
}

/** Whether the pane opens by itself at session start and on attach. */
export function opensPane(placement: Placement): boolean {
  return placement !== 'band'
}

/** Whether the band draws, given whether the pane is placed right now. */
export function bandShows(placement: Placement, isPanePlaced: boolean): boolean {
  switch (placement) {
    case 'both':
    case 'band':
      return true
    case 'pane':
      return false
    case 'auto':
      return !isPanePlaced
  }
}

files.hooks/resolver.ts:
// Event -> Vessel state resolver. Pure: no `$`, no timers. A port of the
// rules in eidola-runtime/docs/spec/vessel-reactivity.md, driven by engine
// events instead of editor shell hooks.

import type { Mood, VesselView } from '../types'

export type Model = {
  /**
   * What the drawings follow. Working from a prompt to the turn's end,
   * through every tool and gap; attention while blocked on the person;
   * idle otherwise. Tools never change it, so it holds steady.
   */
  mood: Mood
  /** Tool calls running right now (parallel tools keep `working` steady). */
  inFlight: number
  /** Tool calls since the turn began: decides `success` vs `responding`. */
  toolsThisTurn: number
}

export type TurnEndReason = 'answer' | 'aborted' | 'refusal' | 'error'

export type Signal =
  | { kind: 'session' }
  | { kind: 'prompt' }
  | { kind: 'turnStart' }
  | { kind: 'toolStart'; tool: string }
  | { kind: 'toolEnd'; tool: string; isOk: boolean }
  | { kind: 'ask'; tool: string }
  | { kind: 'compact' }
  | { kind: 'turnEnd'; reason: TurnEndReason }

export type Step = {
  model: Model
  /** Shown now. */
  view: VesselView
  /** Shown after `ms` unless another signal arrives first. */
  then?: { ms: number; view: VesselView }
}

/** Timings, from vessel.yaml's `playback` defaults. */
export const HOLD = {
  waitingMs: 900,
  errorMs: 1800,
  successMs: 3000,
  turnErrorMs: 4000,
} as const

export const EMPTY: Model = { mood: 'idle', inFlight: 0, toolsThisTurn: 0 }

/** Tools whose call waits on the person's answer: a question, a plan to approve. */
export const ASKING_TOOLS: ReadonlySet<string> = new Set(['AskUserQuestion', 'ExitPlanMode'])

const IDLE: VesselView = { state: 'idle', detail: '' }
const THINKING: VesselView = { state: 'thinking', detail: '' }

function plural(n: number, word: string): string {
  return `${n} ${word}${n === 1 ? '' : 's'}`
}

function working(tool: string, inFlight: number): VesselView {
  return {
    state: 'working',
    detail: inFlight > 1 ? `${tool} · ${inFlight} running` : tool,
  }
}

export function step(model: Model, signal: Signal): Step {
  switch (signal.kind) {
    case 'session':
      return { model: EMPTY, view: IDLE }

    case 'prompt':
    case 'turnStart':
      return { model: { mood: 'working', inFlight: 0, toolsThisTurn: 0 }, view: THINKING }

    case 'toolStart': {
      const next: Model = {
        mood: ASKING_TOOLS.has(signal.tool) ? 'attention' : 'working',
        inFlight: model.inFlight + 1,
        toolsThisTurn: model.toolsThisTurn + 1,
      }
      return { model: next, view: working(signal.tool, next.inFlight) }
    }

    case 'toolEnd': {
      const next: Model = { ...model, mood: 'working', inFlight: Math.max(0, model.inFlight - 1) }
      if (!signal.isOk) {
        return {
          model: next,
          view: { state: 'error', detail: `${signal.tool} failed` },
          then: { ms: HOLD.errorMs, view: THINKING },
        }
      }
      if (next.inFlight > 0) {
        return { model: next, view: working(signal.tool, next.inFlight) }
      }
      return {
        model: next,
        view: { state: 'waiting', detail: `${signal.tool} done` },
        then: { ms: HOLD.waitingMs, view: THINKING },
      }
    }

    case 'ask':
      return {
        model: { ...model, mood: 'attention' },
        view: { state: 'attention', detail: `${signal.tool} needs your OK` },
      }

    case 'compact':
      return { model: { ...model, mood: 'working' }, view: { state: 'attention', detail: 'Compacting' } }

    case 'turnEnd': {
      const next: Model = { mood: 'idle', inFlight: 0, toolsThisTurn: model.toolsThisTurn }
      if (signal.reason === 'aborted') {
        return { model: next, view: IDLE }
      }
      if (signal.reason === 'error' || signal.reason === 'refusal') {
        return {
          model: next,
          view: { state: 'error', detail: 'Turn ended in an error' },
          then: { ms: HOLD.turnErrorMs, view: IDLE },
        }
      }
      const view: VesselView =
        model.toolsThisTurn > 0
          ? { state: 'success', detail: plural(model.toolsThisTurn, 'tool call') }
          : { state: 'responding', detail: 'Replied' }
      return { model: next, view, then: { ms: HOLD.successMs, view: IDLE } }
    }
  }
}

