    frames: [
      { tail: 0, dots: face(EYES.wide, CHEEKS, MOUTH.o, BANG) },
      { tail: 1, dots: face(EYES.wide, CHEEKS, MOUTH.o) },
    ],
  },
  success: {
    frameS: 0.3,
    bobS: 0.6,
    frames: [
      { tail: 0, dots: face(EYES.happy, CHEEKS, MOUTH.smile, plus(2, 4, 'y'), [[17, 2, 'y']]) },
      { tail: 1, dots: face(EYES.happy, CHEEKS, MOUTH.smile, plus(17, 3, 'y'), [[2, 6, 'y']]) },
    ],
  },
  responding: {
    frameS: 0.2,
    bobS: 1.2,
    frames: [
      { tail: 0, dots: face(EYES.open, CHEEKS, MOUTH.open) },
      { tail: 1, dots: face(EYES.open, CHEEKS, MOUTH.small) },
    ],
  },
  error: {
    frameS: 0.6,
    bobS: 0,
    frames: [
      { tail: 0, dots: face(EYES.x, MOUTH.frown, DROP) },
      { tail: 1, dots: face(EYES.x, MOUTH.frown) },
    ],
  },
  waiting: {
    frameS: 0.45,
    bobS: 1.6,
    frames: [
      { tail: 0, dots: face(EYES.left, CHEEKS, MOUTH.small) },
      { tail: 1, dots: face(EYES.right, CHEEKS, MOUTH.small) },
    ],
  },
  sleeping: {
    frameS: 0.9,
    bobS: 3.6,
    frames: [
      { tail: 0, dots: face(EYES.closed, MOUTH.o, Z_SMALL) },
      { tail: 1, dots: face(EYES.closed, MOUTH.o, Z_BIG) },
    ],
  },
}

export function compose(frame: Frame): Grid {
  const rows = [...BODY, ...TAILS[frame.tail]]
  const grid = rows.map(row => row.split(''))
  for (const [x, y, ch] of frame.dots) {
    const row = grid[y]
    if (row !== undefined && x >= 0 && x < GRID) {
      row[x] = ch
    }
  }
  return grid
}

/** Horizontal runs of one color become one rect, to keep the SVG small. */
export function rects(grid: Grid, palette: Palette): string {
  const out: string[] = []
  grid.forEach((row, y) => {
    let x = 0
    while (x < row.length) {
      const ch = row[x]
      if (ch === '.') {
        x += 1
        continue
      }
      let end = x + 1
      while (end < row.length && row[end] === ch) end += 1
      const fill = palette[ch as keyof Palette] ?? '#ff00ff'
      out.push(`<rect x="${x}" y="${y}" width="${end - x}" height="1" fill="${fill}"/>`)
      x = end
    }
  })
  return out.join('')
}

const r = (n: number) => Math.round(n * 1000) / 1000

/** The whole animated Vessel for one state, as SVG markup. */
export function vesselSvg(state: VesselState, palette: Palette, size: number): string {
  const anim = ANIMATIONS[state]
  const n = anim.frames.length
  const cycle = r(anim.frameS * n)
  const slice = r(100 / n)

  const delays = anim.frames
    .map((_, i) => `.d${i}{animation-delay:-${r(((n - i) % n) * anim.frameS)}s}`)
    .join('')
  const bob =
    anim.bobS > 0
      ? `.bob{animation:bob ${anim.bobS}s steps(1,end) infinite}` +
        '@keyframes bob{0%{transform:translateY(0)}50%{transform:translateY(-1px)}100%{transform:translateY(0)}}'
      : ''
  const css =
    `.f{opacity:0;animation:fr ${cycle}s steps(1,end) infinite}.f0{opacity:1}` +
    `@keyframes fr{0%{opacity:1}${slice}%{opacity:0}100%{opacity:0}}` +
    delays +
    bob +
    '@media (prefers-reduced-motion:reduce){.f,.bob{animation:none}}'

  const frames = anim.frames
    .map((frame, i) => `<g class="f f${i === 0 ? '0' : 'n'} d${i}">${rects(compose(frame), palette)}</g>`)
    .join('')

  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 -1 ${GRID} ${GRID + 1}" ` +
    `width="${size}" height="${Math.round((size * (GRID + 1)) / GRID)}" shape-rendering="crispEdges">` +
    `<style>${css}</style><g class="bob">${frames}</g></svg>`
  )
}

/** Terminal fallback: one line per state. */
export const FACES: Record<VesselState, string> = {
  idle: '( o_o )',
  thinking: '( o_o ) . o O',
  working: '( >_< ) *',
  attention: '( O_O ) !',
  success: '( ^_^ ) +',
  responding: '( o0o )',
  error: '( x_x )',
  waiting: '( o_o)>',
  sleeping: '( -_- ) z',
}

files.hooks/field.ts:
// The field engine. A scene is a sampler: for a point and a frame it gives
// a layer and a brightness. The engine samples it onto a grid sized to the
// slot, once per frame, and an ink turns the grid into SVG:
//
//   glyph     a character per cell, from a ramp of dim to dense
//   pixel     a block per cell, dithered between a layer's shades
//   particle  a dot per lit cell, sized by brightness
//
// Each layer names its ink, so one scene can mix them: a pixel creature in
// particle water. Frames cycle by CSS, locked to the wall clock, so a
// redraw for a new state carries the motion on unbroken.

export type Ink = 'glyph' | 'pixel' | 'particle'
export const INKS: readonly Ink[] = ['glyph', 'pixel', 'particle']

/** How one layer of a scene looks in each ink. */
export type LayerStyle = {
  /** glyph: characters from dim to dense; a space draws nothing. */
  chars: string
  /** pixel: shades from dim to bright. */
  shades: string[]
  /** glyph and particle: the fill, a colour or a paint server. */
  fill: string
  opacity?: number
  /** Drawn with a soft bloom. */
  isGlowing?: boolean
  /** The ink this layer draws in; the scene's when absent. */
  ink?: Ink
}

/** [layer, brightness]: layer 0 draws nothing; brightness runs 0 to 1. */
export type Cell = readonly [number, number]
export const EMPTY: Cell = [0, 0]

export type FieldScene = {
  width: number
  height: number
  /** Index 0 is the empty layer and is never drawn. */
  layers: LayerStyle[]
  /** The ink of any layer that names none. */
  ink: Ink
  /**
   * A point in pixels, a frame of `frames`: what moves there, or EMPTY.
   * `want` is the layers this pass draws; a scene may skip work for others.
   */
  sample: (x: number, y: number, frame: number, frames: number, want: ReadonlySet<number>) => Cell
  /**
   * What lies still behind it: sampled once and drawn outside the frame
   * cycle, so a backdrop costs one frame however many the scene has. A
   * cell the moving layers reach in any frame is left out of it.
   */
  still?: (x: number, y: number, want: ReadonlySet<number>) => Cell
  /**
   * How the still backdrop moves: a small drift side to side (the default),
   * or a sway from the top edge, as light shafts hang from the surface.
   */
  stillMotion?: 'drift' | 'sway'
  /** Seconds for one pass through the frames. */
  period: number
  /** Markup drawn under the field and over it; defs and CSS the scene needs. */
  under: string
  over: string
  defs: string[]
  css: string[]
}

/** Cell size in pixels and frame count per ink: what the budget allows. */
export const GRID: Record<Ink, { cw: number; ch: number; frames: number }> = {
  glyph: { cw: 8, ch: 14, frames: 8 },
  pixel: { cw: 8, ch: 8, frames: 3 },
  particle: { cw: 9, ch: 9, frames: 3 },
}

const r1 = (n: number) => Math.round(n * 10) / 10

/** A stable value in [0, 1) for a cell: the same every frame and every draw. */
export function hash(x: number, y: number): number {
  const s = Math.sin(x * 127.1 + y * 311.7) * 43758.5453
  return s - Math.floor(s)
}

/** Smooth value noise in [0, 1). */
export function noise(x: number, y: number): number {
  const xi = Math.floor(x)
  const yi = Math.floor(y)
  const xf = x - xi
  const yf = y - yi
  const u = xf * xf * (3 - 2 * xf)
  const v = yf * yf * (3 - 2 * yf)
  const a = hash(xi, yi)
  const b = hash(xi + 1, yi)
  const c = hash(xi, yi + 1)
  const d = hash(xi + 1, yi + 1)
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v
}

export const clamp01 = (n: number) => (n < 0 ? 0 : n > 1 ? 1 : n)
export const smoothstep = (a: number, b: number, x: number) => {
  const t = clamp01((x - a) / (b - a))
  return t * t * (3 - 2 * t)
}

/** 4×4 ordered dither thresholds. */
const BAYER = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5].map(n => (n + 0.5) / 16)

type Sampled = { cols: number; rows: number; layer: Uint8Array[]; value: Float32Array[]; still?: { layer: Uint8Array; value: Float32Array } }

/** The scene sampled on one ink's grid, keeping only the layers drawn in that ink. */
function sampleAll(scene: FieldScene, cw: number, ch: number, frames: number, keep: Set<number>): Sampled {
  const cols = Math.floor(scene.width / cw)
  const rows = Math.floor(scene.height / ch)
  const layer: Uint8Array[] = []
  const value: Float32Array[] = []
  for (let f = 0; f < frames; f += 1) {
    const L = new Uint8Array(cols * rows)
    const V = new Float32Array(cols * rows)
    for (let y = 0; y < rows; y += 1) {
      for (let x = 0; x < cols; x += 1) {
        const [l, v] = scene.sample((x + 0.5) * cw, (y + 0.5) * ch, f, frames, keep)
        if (l > 0 && v > 0 && keep.has(l)) {
          L[y * cols + x] = l
          V[y * cols + x] = clamp01(v)
        }
      }
    }
    layer.push(L)
    value.push(V)
  }
  let still: Sampled['still']
  if (scene.still) {
    const L = new Uint8Array(cols * rows)
    const V = new Float32Array(cols * rows)
    for (let y = 0; y < rows; y += 1) {
      for (let x = 0; x < cols; x += 1) {
        const i = y * cols + x
        if (layer.some(f => f[i] !== 0)) {
          continue
        }
        const [l, v] = scene.still((x + 0.5) * cw, (y + 0.5) * ch, keep)
        if (l > 0 && v > 0 && keep.has(l)) {
          L[i] = l
          V[i] = clamp01(v)
        }
      }
    }
    still = { layer: L, value: V }
  }
  return { cols, rows, layer, value, still }
}

function glyphFrame(scene: FieldScene, s: Grid, cw: number, ch: number): string {
  const out: string[] = []
  scene.layers.forEach((style, l) => {
    if (l === 0) {
      return
    }
    const texts: string[] = []
    for (let y = 0; y < s.rows; y += 1) {
      let line = ''
      let first = -1
      let last = -1
      for (let x = 0; x < s.cols; x += 1) {
        const i = y * s.cols + x
        let c = ' '
        if (s.layer[i] === l) {
          // Lifted and jittered a little, so mid-tones don't band into rows of one character.
          const v = clamp01(Math.pow(s.value[i]!, 0.75) + (hash(x, y) - 0.5) * 0.14)
          c = style.chars[Math.min(style.chars.length - 1, Math.floor(v * style.chars.length))]!
        }
        if (c !== ' ') {
          if (first < 0) {
            first = x
          }
          last = x
        }
        line += c
      }
      if (first >= 0) {
        texts.push(`<text x="${first * cw}" y="${r1(y * ch + ch * 0.78)}" textLength="${(last - first + 1) * cw}">${line.slice(first, last + 1)}</text>`)
      }
    }
    if (texts.length) {
      out.push(layerGroup(style, texts.join(''), style.fill))
    }
  })
  return out.join('')
}

function pixelFrame(scene: FieldScene, s: Grid): string {
  const out: string[] = []
  scene.layers.forEach((style, l) => {
    if (l === 0) {
      return
    }
    const n = style.shades.length
    const runs: string[][] = style.shades.map(() => [])
    for (let y = 0; y < s.rows; y += 1) {
      let runLevel = -1
      let runStart = 0
      const flush = (end: number) => {
        if (runLevel >= 0) {
          const len = end - runStart
          runs[runLevel]!.push(`M${runStart} ${y}h${len}v1h-${len}z`)
        }
      }
      for (let x = 0; x < s.cols; x += 1) {
        const i = y * s.cols + x
        let level = -1
        if (s.layer[i] === l) {
          const at = s.value[i]! * (n - 1)
          const base = Math.floor(at)
          level = Math.min(n - 1, at - base > BAYER[(y % 4) * 4 + (x % 4)]! ? base + 1 : base)
        }
        if (level !== runLevel) {
          flush(x)
          runLevel = level
          runStart = x
        }
      }
      flush(s.cols)
    }
    const paths = runs.map((d, k) => (d.length ? `<path fill="${style.shades[k]}" d="${d.join('')}"/>` : '')).join('')
    if (paths) {
      out.push(layerGroup(style, paths))
    }
  })
  return out.join('')
}

/** One grid's worth: a frame, or the still backdrop. */
type Grid = { cols: number; rows: number; layer: Uint8Array; value: Float32Array }

const DOT_SIZES = [0.32, 0.55, 0.85]

function particleFrame(scene: FieldScene, s: Grid, cw: number, ch: number): string {
  const out: string[] = []
  scene.layers.forEach((style, l) => {
    if (l === 0) {
      return
    }
    const buckets: string[][] = DOT_SIZES.map(() => [])
    for (let y = 0; y < s.rows; y += 1) {
      for (let x = 0; x < s.cols; x += 1) {
        const i = y * s.cols + x
        if (s.layer[i] !== l) {
          continue
        }
        const v = s.value[i]!
        if (v < 0.08) {
          continue
        }
        const k = v < 0.4 ? 0 : v < 0.72 ? 1 : 2
        const jx = (hash(x, y) - 0.5) * cw * 0.6
        const jy = (hash(y, x) - 0.5) * ch * 0.6
        buckets[k]!.push(`M${Math.round((x + 0.5) * cw + jx)} ${Math.round((y + 0.5) * ch + jy)}h0`)
      }
    }
    const paths = buckets
      .map((d, k) => (d.length ? `<path stroke="${style.fill}" stroke-width="${r1(DOT_SIZES[k]! * cw)}" d="${d.join('')}"/>` : ''))
      .join('')
    if (paths) {
      out.push(layerGroup(style, paths))
    }
  })
  return out.join('')
}

function layerGroup(style: LayerStyle, body: string, fill?: string): string {
  const attrs =
    (fill ? ` fill="${fill}"` : '') +
    (style.opacity !== undefined ? ` opacity="${style.opacity}"` : '') +
    (style.isGlowing ? ' filter="url(#bloom)"' : '')
  return `<g${attrs}>${body}</g>`
}

const BLOOM =
  '<filter id="bloom" x="-20%" y="-20%" width="140%" height="140%"><feGaussianBlur stdDeviation="2.2" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter>'

/** What a drawing may come to: under the Svg element's 131,072, with room to spare. */
export const BUDGET = 120_000

/** The slot area GRID's cell sizes were set for: a 412 × 1442 dock. */
const REFERENCE_AREA = 412 * 1442

/**
 * The scene drawn, its frames cycling from where the clock says. Runs of
 * layers that share an ink are one pass, each on its own grid, drawn in
 * layer order. `only` draws every layer in one ink, to compare inks.
 *
 * Cells grow with the slot so a larger one costs no more: from a scale set
 * by its area, and coarser again until the drawing fits the budget.
 */
export function renderScene(scene: FieldScene, nowMs: number, only?: Ink): string {
  let scale = Math.max(1, Math.sqrt((scene.width * scene.height) / REFERENCE_AREA))
  let svg = renderAt(scene, nowMs, only, scale)
  for (let tries = 0; svg.length > BUDGET && tries < 6; tries += 1) {
    scale *= 1.2
    svg = renderAt(scene, nowMs, only, scale)
  }
  return svg
}

function renderAt(scene: FieldScene, nowMs: number, only: Ink | undefined, scale: number): string {
  const W = Math.round(scene.width)
  const H = Math.round(scene.height)
  const P = scene.period
  const clock = (nowMs / 1000) % P

  const passes: Array<{ ink: Ink; layers: number[] }> = []
  scene.layers.forEach((style, l) => {
    if (l === 0) {
      return
    }
    const ink = only ?? style.ink ?? scene.ink
    const last = passes[passes.length - 1]
    if (last?.ink === ink) {
      last.layers.push(l)
    } else {
      passes.push({ ink, layers: [l] })
    }
  })

  const css: string[] = []
  const reduced: string[] = []
  const body = passes
    .map((pass, p) => {
      const base = GRID[pass.ink]
      const cw = Math.round(base.cw * scale)
      const ch = Math.round(base.ch * scale)
      const frames = base.frames
      const s = sampleAll(scene, cw, ch, frames, new Set(pass.layers))
      const draw = (g: Grid) =>
        pass.ink === 'glyph' ? glyphFrame(scene, g, cw, ch) : pass.ink === 'pixel' ? pixelFrame(scene, g) : particleFrame(scene, g, cw, ch)
      const slot = P / frames

      let stillMarkup = s.still ? draw({ cols: s.cols, rows: s.rows, ...s.still }) : ''
      if (stillMarkup) {
        // The still backdrop drifts a little, so it never reads as frozen.
        // Pixel ink draws in cell units, the others in pixels.
        const drift = pass.ink === 'pixel' ? 0.5 : r1(cw * 0.5)
        const delay = r1(-((nowMs / 1000) % 18))
        css.push(
          scene.stillMotion === 'sway'
            ? `.s${p}{transform-box:view-box;transform-origin:${r1(W / 2)}px 0;animation:s${p} 7s ${delay}s ease-in-out infinite alternate}@keyframes s${p}{from{transform:skewX(-2.5deg)}to{transform:skewX(2.5deg)}}`
            : `.s${p}{animation:s${p} 9s ${delay}s ease-in-out infinite alternate}@keyframes s${p}{from{transform:translate(-${drift}px,0)}to{transform:translate(${drift}px,0)}}`,
        )
        reduced.push(`.s${p}`)
        stillMarkup = `<g class="s${p}">${stillMarkup}</g>`
      }

      const frameBodies = Array.from({ length: frames }, (_, f) => draw({ cols: s.cols, rows: s.rows, layer: s.layer[f]!, value: s.value[f]! }))
      let frameMarkup = ''
      if (frameBodies.some(b => b)) {
        css.push(`.p${p}{opacity:0;animation:p${p} ${P}s steps(1,end) infinite}@keyframes p${p}{0%{opacity:1}${r1(100 / frames)}%{opacity:0}100%{opacity:0}}`)
        reduced.push(`.p${p}`)
        frameMarkup = frameBodies
          .map((b, f) => {
            const delay = r1(-(((P - f * slot) % P) + clock) % P)
            return `<g class="p${p}${f === 0 ? ' f0' : ''}" style="animation-delay:${delay}s">${b}</g>`
          })
          .join('')
      }

      const attrs =
        pass.ink === 'glyph'
          ? ` font-family="ui-monospace,Menlo,Consolas,monospace" font-size="${r1(ch * 1.02)}" font-weight="700" style="white-space:pre"`
          : pass.ink === 'pixel'
            ? ` transform="scale(${cw} ${ch})" shape-rendering="crispEdges"`
            : ' fill="none" stroke-linecap="round"'
      return stillMarkup || frameMarkup ? `<g${attrs}>${stillMarkup}${frameMarkup}</g>` : ''
    })
    .join('')

  if (reduced.length) {
    css.push(`@media (prefers-reduced-motion:reduce){${reduced.join(',')}{animation:none}.f0{opacity:1}}`)
  }
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" xml:space="preserve" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}">` +
    `<style>${css.join('')}${scene.css.join('')}</style><defs>${BLOOM}${scene.defs.join('')}</defs>` +
    `${scene.under}${body}${scene.over}</svg>`
  )
}

files.hooks/kraken.ts:
// The Kraken as a field scene, for any ink. The pane is deep water with the
// Kraken spread across it; the band is the sea just under the surface, a
// hull above and arms rising out of the dark. Light falls in soft shafts
// that sway; runes and eyes glow; the arms sway through the frames.

import type { VesselState } from '../types'
import { EMPTY, clamp01, hash, noise, smoothstep } from './field'
import type { Cell, FieldScene, LayerStyle } from './field'

type Pt = [number, number]
const TAU = Math.PI * 2

// Layers, in drawing order.
const WATER = 1
export const BODY = 2
export const DETAIL = 3
export const GLOW = 4
const BUBBLE = 5
/** The iris up close: a palette of its own, from a deep teal rim to a pale centre. */
export const IRIS = 6

/**
 * The live Kraken's eyes and runes by mood: cyan at rest (the layers' own),
 * crimson at work, gold when it needs you. Its glow first, then its iris.
 */
export const CRIMSON = { glow: ['#5a0a10', '#b81a24', '#ff3a40', '#ffc0c0'], iris: ['#2a0608', '#480a0e', '#6a1016', '#8e1a20', '#b4282c', '#d64a48', '#f08a80', '#ffd6d0'] }
export const GOLD = { glow: ['#5a3a06', '#c08a10', '#ffcf3a', '#fff2b0'], iris: ['#2a1a04', '#483008', '#6a480c', '#8e6612', '#b4881c', '#d6aa36', '#f0d070', '#fff4c8'] }

export function layers(isAngry: boolean): LayerStyle[] {
  const glow = isAngry ? '#ff5a4a' : '#5ff6ff'
  return [
    { chars: ' ', shades: [], fill: 'none' },
    // The water's motes and the bubbles are particles; the Kraken is pixels.
    { chars: " .'`:-~", shades: ['#0d3442', '#16495a', '#246475', '#3b8594'], fill: '#8fe3ec', opacity: 0.5, ink: 'particle' },
    {
      chars: ' .:;+x*%#@',
      shades: ['#0c161b', '#15242b', '#20353e', '#2f4a54', '#43636d', '#5f8189', '#87a7ae', '#b4cdd2'],
      fill: 'url(#skin)',
    },
    { chars: 'oO@', shades: ['#3c5860', '#9db7bb', '#d6e6e8'], fill: '#d2e4e7' },
    {
      chars: '+*#',
      shades: isAngry ? ['#5a1008', '#b8281a', '#ff5a4a', '#ffd2c8'] : ['#0b5c66', '#1fb2c0', '#5ff6ff', '#dcffff'],
      fill: glow,
      isGlowing: true,
    },
    { chars: '°oO', shades: ['#3b8594', '#8fd6df', '#d8f6fa'], fill: '#c9f3ff', opacity: 0.8, ink: 'particle' },
    { chars: '.:+*#', shades: ['#062a30', '#0a434c', '#0f5e68', '#178089', '#24a3ab', '#4cc6c9', '#93e4e0', '#d9fbf6'], fill: '#4cc6c9', isGlowing: true },
  ]
}

// ── Arms ───────────────────────────────────────────────────────────────

export type Arm = { pts: Pt[]; w: number[]; len: number; box: [number, number, number, number] }

type ArmSpec = { x: number; y: number; angle: number; len: number; curl: number; amp: number; k: number; w0: number }

function buildArm(a: ArmSpec, phase: number, n = 14): Arm {
  const pts: Pt[] = [[a.x, a.y]]
  let x = a.x
  let y = a.y
  const step = a.len / n
  for (let i = 1; i <= n; i += 1) {
    const s = i / n
    const theta = a.angle + a.curl * s * s * s + a.amp * Math.sin(TAU * a.k * s - phase) * s
    x += Math.cos(theta) * step
    y += Math.sin(theta) * step
    pts.push([x, y])
  }
  const w = pts.map((_, i) => Math.max(1.5, a.w0 * Math.pow(1 - i / n, 0.8)))
  const pad = a.w0
  const xs = pts.map(p => p[0])
  const ys = pts.map(p => p[1])
  return { pts, w, len: a.len, box: [Math.min(...xs) - pad, Math.min(...ys) - pad, Math.max(...xs) + pad, Math.max(...ys) + pad] }
}

/** Where a point falls on an arm: t along it, side across it (-1 to 1, signed), or undefined if off it. */
function onArm(arm: Arm, x: number, y: number): { t: number; side: number } | undefined {
  const [x0, y0, x1, y1] = arm.box
  if (x < x0 || x > x1 || y < y0 || y > y1) {
    return undefined
  }
  let best: { t: number; side: number } | undefined
  let bestD = Infinity
  const n = arm.pts.length - 1
  for (let i = 0; i < n; i += 1) {
    const [ax, ay] = arm.pts[i]!
    const [bx, by] = arm.pts[i + 1]!
    const dx = bx - ax
    const dy = by - ay
    const l2 = dx * dx + dy * dy || 1
    const u = clamp01(((x - ax) * dx + (y - ay) * dy) / l2)
    const px = ax + dx * u
    const py = ay + dy * u
    const d = Math.hypot(x - px, y - py)
    const half = (arm.w[i]! + (arm.w[i + 1]! - arm.w[i]!) * u) / 2
    if (d <= half && d < bestD) {
      bestD = d
      const cross = dx * (y - ay) - dy * (x - ax)
      best = { t: (i + u) / n, side: (cross < 0 ? -1 : 1) * (d / half) }
    }
  }
  return best
}

// ── The Kraken ─────────────────────────────────────────────────────────

export type Runes = 'faint' | 'calm' | 'pulse' | 'bright'
const RUNE_LEVEL: Record<Runes, number> = { faint: 0.25, calm: 0.55, pulse: 0.8, bright: 1 }

export type Pose = {
  cx: number
  cy: number
  /** Mantle width. */
  s: number
  /** 1 lit by the surface, toward 0 lost in the dark. */
  depth: number
  runes: Runes
  /** The runes' glow, 0 to 1, in place of `runes`' level: what a live drawing eases. */
  runeLevel?: number
  isAngry?: boolean
  /** 0 open, 1 shut. */
  lid?: number
  /** Pupils: -1 left, 1 right. */
  look?: number
  /** Whether it has arms of its own. */
  hasArms: boolean
  reach?: number
  sway: number
}

const ARM_ANGLES = [-28, 14, 48, 76, 104, 132, 166, 208]

export function krakenArms(p: Pose, phase: number): Arm[] {
  if (!p.hasArms) {
    return []
  }
  return ARM_ANGLES.map((deg, i) => {
    const a = (deg * Math.PI) / 180
    const h = hash(i, 7)
    return buildArm(
      {
        x: p.cx + Math.cos(a) * p.s * 0.34,
        y: p.cy + p.s * 0.3 + Math.sin(a) * p.s * 0.1,
        angle: a + (h - 0.5) * 0.3,
        len: p.s * (p.reach ?? 2.8) * (0.8 + hash(i, 3) * 0.4),
        curl: (i % 2 ? 1 : -1) * (1.8 + h * 1.6),
        amp: p.sway * (0.8 + hash(i, 5) * 0.4),
        k: 0.6 + hash(i, 9) * 0.3,
        w0: p.s * 0.4,
      },
      phase + i * 0.9,
    )
  })
}

/** The Kraken at a point: its body, suckers, runes and eyes. */
export function krakenAt(p: Pose, arms: Arm[], x: number, y: number, frame: number): Cell | undefined {
  const { cx, cy, s } = p
  const lvl = p.runeLevel ?? RUNE_LEVEL[p.runes]

  // Eyes.
  for (const side of [-1, 1]) {
    const ex = cx + side * s * 0.44
    const ey = cy + s * 0.1
    const er = s * 0.1
    const d = Math.hypot(x - ex, (y - ey) * 1.2)
    if (d < er) {
      const lid = p.lid ?? 0
      if (y - ey < -er + 2 * er * lid) {
        return [BODY, 0.45 * p.depth]
      }
      const px = ex + (p.look ?? 0) * er * 0.3
      if (Math.abs(y - ey) < er * 0.2 && Math.abs(x - px) < er * 0.62) {
        return [BODY, 0.02]
      }
      return [GLOW, 0.75 + 0.25 * (1 - d / er)]
    }
    if (d < er * 1.7) {
      return [BODY, (0.7 + 0.2 * (1 - d / (er * 1.7))) * p.depth]
    }
  }

  // Mantle: a sack swept up from a wide rim.
  const u = (x - cx) / s
  const v = (y - cy) / s
  const sack = (u / 0.62) ** 2 + ((v + 0.42) / 0.78) ** 2
  const rim = (u / 0.6) ** 2 + ((v - 0.12) / 0.3) ** 2
  if (sack < 1 || rim < 1) {
    const top = smoothstep(0.2, -0.9, v) // lighter toward the crown
    const edge = Math.min(1, Math.max(sack, rim < 1 ? 0 : 1))
    const mottle = 0.82 + 0.25 * noise(x / (s * 0.12), y / (s * 0.12))
    const rimLight = smoothstep(0.75, 1, sack) * smoothstep(0, -0.7, v) * 0.35
    return [BODY, clamp01((0.28 + 0.5 * top + rimLight) * mottle * (1 - 0.15 * edge) * p.depth)]
  }

  // Arms.
  for (const arm of arms) {
    const hit = onArm(arm, x, y)
    if (!hit) {
      continue
    }
    const { t, side } = hit
    const along = t * arm.len
    // Ringed suckers down the underside.
    if (side < -0.38 && side > -0.92 && t < 0.88) {
      const spacing = Math.max(6, arm.w[Math.floor(t * (arm.w.length - 1))]! * 0.45)
      const ph = (along / spacing) % 1
      if (ph < 0.5) {
        return [DETAIL, (0.55 + 0.4 * (1 - Math.abs(ph - 0.25) * 4)) * p.depth]
      }
    }
    // Runes down the spine.
    if (Math.abs(side) < 0.16 && t > 0.05 && t < 0.8) {
      const mark = Math.floor(along / 9) % 6
      if (mark === 0 || mark === 2 || mark === 3) {
        return [GLOW, lvl * 0.9]
      }
    }
    // Lit along the top, shadowed underneath, dark at the edges.
    const lit = 0.3 + 0.45 * clamp01(side * 0.6 + 0.5)
    const edgeDark = Math.abs(side) > 0.88 ? 0.55 : 1
    const mottle = 0.85 + 0.2 * noise(x / 14, y / 14)
    return [BODY, clamp01(lit * edgeDark * mottle * (1 - 0.35 * t) * p.depth)]
  }
  return undefined
}

// ── Water ──────────────────────────────────────────────────────────────

type Shaft = { x: number; w: number; slope: number; sway: number; strength: number }

function shaftsFor(W: number, count: number, seed: number): Shaft[] {
  return Array.from({ length: count }, (_, i) => ({
    x: W * ((i + 0.5) / count) + (hash(i, seed) - 0.5) * W * 0.12,
    w: W * (0.025 + hash(i, seed + 1) * 0.04),
    slope: 0.12 + hash(i, seed + 2) * 0.12,
    sway: W * 0.02,
    strength: 0.5 + hash(i, seed + 3) * 0.5,
  }))
}

/** Soft light shafts, caustic shimmer near the surface, specks and bubbles. */
function waterAt(W: number, H: number, shafts: Shaft[], x: number, y: number, phase: number, dim: number, surfaceY: number): Cell {
  let light = 0
  for (const [i, sh] of shafts.entries()) {
    const centre = sh.x + sh.slope * (y - surfaceY) + Math.sin(phase + i * 1.7) * sh.sway
    const across = (x - centre) / sh.w
    light += Math.exp(-across * across) * sh.strength
  }
  const fall = Math.exp(-(y - surfaceY) / (H * 0.45))
  let v = light * fall * (0.55 + 0.45 * noise(x / 18 + phase * 0.3, y / 26))
  // Caustics: a band of shimmer just below the surface.
  const band = Math.exp(-(((y - surfaceY) / (H * 0.035)) ** 2))
  v += band * smoothstep(0.45, 0.8, noise(x / 11 + phase * 0.6, y / 7)) * 0.9
  // Specks.
  if (hash(Math.floor(x / 5), Math.floor(y / 5)) > 0.985) {
    v = Math.max(v, 0.35)
  }
  v *= dim
  return v > 0.14 ? [WATER, v] : EMPTY
}

/** Bubbles rising through the frames: a column of small rings. */
function bubbleAt(x: number, y: number, cx: number, spread: number, bottom: number, height: number, frame: number, frames: number): Cell | undefined {
  for (let i = 0; i < 14; i += 1) {
    const bx = cx + (hash(i, 31) - 0.5) * spread + Math.sin(frame * 1.3 + i) * 4
    const travel = ((hash(i, 37) + frame / frames) % 1) * height
    const by = bottom - travel
    const br = 3 + hash(i, 41) * 4
    if (Math.hypot(x - bx, y - by) < br) {
      return [BUBBLE, 0.35 + hash(i, 43) * 0.65]
    }
  }
  return undefined
}

function backdrop(W: number, H: number, top: string, mid: string, defs: string[]): string {
  defs.push(
    `<linearGradient id="deep" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${top}"/><stop offset=".35" stop-color="${mid}"/><stop offset="1" stop-color="#02070b"/></linearGradient>`,
    `<linearGradient id="skin" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="0" y2="${H}"><stop offset="0" stop-color="#d4e8eb"/><stop offset="1" stop-color="#7c9ba2"/></linearGradient>`,
    `<radialGradient id="vig" cx=".5" cy=".5" r=".75"><stop offset=".55" stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".6"/></radialGradient>`,
  )
  return `<rect width="${W}" height="${H}" fill="url(#deep)"/>`
}

const OVER = (W: number, H: number) =>
  `<rect width="${W}" height="${H}" fill="url(#vig)"/><rect x="1" y="1" width="${W - 2}" height="${H - 2}" fill="none" stroke="#bfefff" stroke-opacity=".12" stroke-width="2"/>`

// ── Scenes ─────────────────────────────────────────────────────────────

function deepPose(state: VesselState, W: number, H: number): Pose {
  const s = Math.min(W * 0.44, H * 0.26)
  const base = { cx: W * 0.5, cy: H * 0.42, s, depth: 1, hasArms: true, sway: 0.3 }
  switch (state) {
    case 'idle':
      return { ...base, cx: W * 0.55, cy: H * 0.74, depth: 0.45, runes: 'faint', sway: 0.2 }
    case 'sleeping':
      return { ...base, cy: H * 0.82, depth: 0.3, runes: 'faint', lid: 1, sway: 0.12 }
    case 'thinking':
      return { ...base, runes: 'pulse', look: 0.4 }
    case 'working':
      return { ...base, cx: W * 0.45, cy: H * 0.38, depth: 0.9, runes: 'bright', look: 0.5, sway: 0.45 }
    case 'responding':
      return { ...base, runes: 'calm', look: -0.3, sway: 0.35 }
    case 'waiting':
      return { ...base, cy: H * 0.56, depth: 0.75, runes: 'faint', lid: 0.5, look: -0.5, sway: 0.2 }
    case 'attention':
      return { ...base, cx: W - s * 0.12, cy: H * 0.4, s: s * 1.35, runes: 'bright', look: -1, hasArms: false }
    case 'success':
      return { ...base, runes: 'bright', sway: 0.4 }
    case 'error':
      return { ...base, cy: H * 0.45, runes: 'bright', isAngry: true, sway: 0.6 }
  }
}

/** Arms that belong to the scene rather than the body: tips round the edge while it peeks. */
function sceneArms(state: VesselState, pose: Pose, W: number, H: number, phase: number): Arm[] {
  if (state === 'attention') {
    // Tips curling round the right edge, below the peering head.
    return [0, 1, 2].map(i =>
      buildArm(
        { x: W + 10, y: H * (0.58 + i * 0.12), angle: Math.PI + (i - 1) * 0.25, len: pose.s * 1.1, curl: (i % 2 ? 1 : -1) * 2.6, amp: 0.3, k: 0.8, w0: pose.s * 0.22 },
        phase + i,
      ),
    )
  }
  return []
}

/** The pane: deep water, the Kraken spread across it. */
export function krakenPaneScene(state: VesselState, W: number, H: number): FieldScene {
  const pose = deepPose(state, W, H)
  const shafts = shaftsFor(W, 5, 11)
  const armsByFrame = new Map<number, Arm[]>()
  const defs: string[] = []
  const under = backdrop(W, H, '#1d6170', '#0a2e3b', defs)
  const busy = state === 'working' || state === 'error'
  return {
    width: W,
    height: H,
    layers: layers(!!pose.isAngry),
    ink: 'pixel',
    period: busy ? 3.2 : state === 'sleeping' ? 10 : 6,
    under,
    over: OVER(W, H),
    defs,
    css: [],
    sample(x, y, frame, frames, want) {
      if (want.has(BODY)) {
        let arms = armsByFrame.get(frame)
        if (!arms) {
          arms = [...sceneArms(state, pose, W, H, (frame / frames) * TAU), ...krakenArms(pose, (frame / frames) * TAU)]
          armsByFrame.set(frame, arms)
        }
        return krakenAt(pose, arms, x, y, frame) ?? EMPTY
      }
      return bubbleAt(x, y, pose.cx, W * 0.7, Math.min(H, pose.cy + pose.s * 0.4), H * 0.6, frame, frames) ?? EMPTY
    },
    still(x, y, want) {
      if (want.has(BODY)) {
        return EMPTY
      }
      return waterAt(W, H, shafts, x, y, 0, state === 'sleeping' ? 0.4 : 1, 0)
    },
  }
}

/** The band: just under the surface, a hull above, arms rising from below. */
export function krakenBandScene(state: VesselState, W: number, H: number): FieldScene {
  const surfaceY = H * 0.14
  const shafts = shaftsFor(W, 8, 23)
  const hx = W * 0.68
  const hl = Math.min(W * 0.09, H * 0.6)
  const isAngry = state === 'error'
  const depth = state === 'idle' ? 0.4 : state === 'sleeping' ? 0.25 : 1
  const runes: Runes = state === 'working' || state === 'error' ? 'bright' : state === 'thinking' ? 'pulse' : 'faint'
  const rising: Array<[number, number, number, number]> =
    state === 'working'
      ? [
          [0.42, 0.35, 1.25, 2.6],
          [0.53, 0.15, 1.35, -2.2],
          [0.6, 0.05, 1.2, 2.4],
          [0.82, -0.35, 1.2, -2.6],
        ]
      : state === 'thinking' || state === 'responding' || state === 'success' || state === 'error'
        ? [
            [0.26, 0.25, 1.05, 2.4],
            [0.4, -0.2, 0.95, -2.2],
          ]
        : state === 'idle'
          ? [[0.12, 0.3, 0.8, 2.2]]
          : []
  const pose: Pose = { cx: W * 0.2, cy: H * 0.7, s: H * 0.55, depth: 1, runes: 'bright', look: -1, hasArms: false, sway: 0, lid: state === 'waiting' ? 0.5 : 0 }
  const showHead = state === 'attention' || state === 'waiting'
  if (state === 'waiting') {
    pose.cy = H * 0.86
  }
  const armsByFrame = new Map<number, Arm[]>()
  const defs: string[] = []
  const under =
    backdrop(W, H, '#3f9aa8', '#0f4757', defs) +
    `<path d="M0 0H${W}V${Math.round(surfaceY)}H0Z" fill="#a8e8f0" fill-opacity=".35"/>` +
    `<path d="M${Math.round(hx - hl)} ${Math.round(surfaceY - 2)}Q${Math.round(hx)} ${Math.round(surfaceY + H * 0.22)} ${Math.round(hx + hl)} ${Math.round(surfaceY - 2)}Z" fill="#051a22"/>`
  return {
    width: W,
    height: H,
    layers: layers(isAngry),
    ink: 'pixel',
    period: state === 'working' || state === 'error' ? 3.2 : 6,
    under,
    over: OVER(W, H),
    defs,
    css: [],
    sample(x, y, frame, frames, want) {
      if (!want.has(BODY)) {
        return bubbleAt(x, y, W * 0.45, W * 0.8, H + 4, H * 0.9, frame, frames) ?? EMPTY
      }
      const phase = (frame / frames) * TAU
      let arms = armsByFrame.get(frame)
      if (!arms) {
        arms = rising.map(([px, lean, reach, curl], i) =>
          buildArm({ x: W * px, y: H + 14, angle: -Math.PI / 2 + lean, len: H * reach, curl, amp: 0.3, k: 0.7, w0: H * 0.3 }, phase + i * 1.3, 12),
        )
        armsByFrame.set(frame, arms)
      }
      const armPose: Pose = { ...pose, depth, runes, isAngry, hasArms: true }
      const k = krakenAt(showHead ? { ...pose, isAngry } : { ...armPose, cx: -1e4, cy: -1e4 }, arms, x, y, frame)
      return k ?? EMPTY
    },
    still(x, y, want) {
      if (want.has(BODY)) {
        return EMPTY
      }
      // Nothing drawn over the hull.
      const hy = surfaceY + H * 0.22 * (1 - ((x - hx) / hl) ** 2) * 0.5
      if (Math.abs(x - hx) < hl && y < hy) {
        return EMPTY
      }
      // The surface overhead: bright, its edge rippling.
      const edge = surfaceY + Math.sin(x / 26) * 2.5 + Math.sin(x / 9) * 1.2
      if (y < edge) {
        return [WATER, 0.75 + 0.25 * noise(x / 8, y / 4)]
      }
      return waterAt(W, H, shafts, x, y, 0, state === 'sleeping' ? 0.4 : 1, surfaceY)
    },
  }
}

// ── Live ───────────────────────────────────────────────────────────────

/**
 * The deep water alone, the same whatever the mood: drawn once as an SVG
 * whose source never changes, under the live Kraken. Since it never
 * reloads, its motion is all CSS and runs on unbroken: soft light sways
 * down from the surface, bubbles rise and wobble, specks of snow drift.
 */
export function krakenWaterScene(W: number, H: number): FieldScene {
  const defs: string[] = []
  const r = (n: number) => Math.round(n * 10) / 10

  // Open water: nothing blocks the light, so no shafts; it only fades with
  // depth, a little brighter toward the surface.
  defs.push(
    `<radialGradient id="glow" cx=".5" cy="0" r=".9"><stop offset="0" stop-color="#bff4ff" stop-opacity=".18"/><stop offset="1" stop-color="#bff4ff" stop-opacity="0"/></radialGradient>`,
  )
  const under = backdrop(W, H, '#1d6170', '#0a2e3b', defs) + `<rect width="${W}" height="${r(H * 0.55)}" fill="url(#glow)"/>`

  // Bubbles: some in streams from below, some loose, each rising the whole height.
  const vents = [W * 0.18, W * 0.62, W * 0.84]
  const bubbles = Array.from({ length: 30 }, (_, i) => {
    const inStream = i < 18
    const x = inStream ? vents[i % vents.length]! + (hash(i, 51) - 0.5) * 14 : hash(i, 52) * W
    const size = 1.5 + hash(i, 53) * 4
    const rise = r(7 + hash(i, 54) * 9)
    const wobble = r(1.2 + hash(i, 55) * 1.6)
    return (
      `<g style="animation:rise ${rise}s ${r(-hash(i, 56) * rise)}s linear infinite">` +
      `<circle cx="${r(x)}" cy="${r(H + 8)}" r="${r(size)}" style="animation:wobble ${wobble}s ${r(-hash(i, 57) * wobble)}s ease-in-out infinite alternate"/></g>`
    )
  }).join('')

  // Marine snow at three depths: far specks tiny, dim and slow, near ones
  // larger, brighter and quicker. The parallax gives the water its depth.
  const depths = [
    { count: 55, size: 0.5, spread: 0.5, fall: [34, 52], opacity: 0.35, seed: 61 },
    { count: 30, size: 0.9, spread: 0.7, fall: [20, 32], opacity: 0.55, seed: 81 },
    { count: 12, size: 1.6, spread: 1, fall: [11, 18], opacity: 0.75, seed: 91 },
  ] as const
  const snow = depths
    .map(d => {
      const specks = Array.from({ length: d.count }, (_, i) => {
        const fall = r(d.fall[0] + hash(i, d.seed) * (d.fall[1] - d.fall[0]))
        return `<circle cx="${r(hash(i, d.seed + 1) * W)}" cy="${r(hash(i, d.seed + 2) * H * 0.9)}" r="${r(d.size + hash(i, d.seed + 3) * d.spread)}" style="animation:snow ${fall}s ${r(-hash(i, d.seed + 4) * fall)}s linear infinite"/>`
      }).join('')
      return `<g fill-opacity="${d.opacity}">${specks}</g>`
    })
    .join('')

  const css =
    `@keyframes rise{from{transform:translateY(0)}to{transform:translateY(${r(-H - 20)}px)}}` +
    '@keyframes wobble{from{transform:translateX(-5px)}to{transform:translateX(5px)}}' +
    `@keyframes snow{0%{transform:translate(0,0);opacity:0}12%{opacity:.7}88%{opacity:.5}100%{transform:translate(14px,${r(H * 0.4)}px);opacity:0}}` +

    '@media (prefers-reduced-motion:reduce){g,circle,path{animation:none!important}}'

  return {
    width: W,
    height: H,
    layers: layers(false),
    ink: 'particle',
    period: 6,
    under,
    over:
      `<g fill="#d9f2ff">${snow}</g>` +
      `<g fill="none" stroke="#c9f3ff" stroke-opacity=".65" stroke-width="1">${bubbles}</g>` +
      OVER(W, H),
    defs,
    css: [css],
    sample() {
      return EMPTY
    },
  }
}

